param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName System.Runtime.Serialization
Add-Type -AssemblyName Microsoft.CSharp
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
$exe=Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'
$assembly=[Reflection.Assembly]::LoadFrom($exe)
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$parametersType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolParameterData',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s58-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$ownsApp=$null-eq$app;if($ownsApp){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.Show();Pump 150
function Field([string]$name){$field=$mainType.GetField($name,$all);if($null-eq$field){return $null};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function Kind([string]$name){[Enum]::Parse($kindType,$name)}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@((Kind $kind),$name,$true,$null))}
function Out($tool,[string]$name){$args=[object[]]@($name,$null);Assert($tool.GetType().GetMethod('TryGetOutputValue').Invoke($tool,$args))('Missing output '+$name);$args[1]}
function Run($tool){$mainType.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($tool,'S58 smoke'))}
function RunFailure($tool){try{Run $tool|Out-Null;throw 'Expected execution failure'}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};return $e.Message}}
function LoadDock($tool){$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($tool.PSObject.BaseObject))|Out-Null}
function CompileFixture([string]$source,[string]$name){$path=Join-Path $temp $name;$provider=New-Object Microsoft.CSharp.CSharpCodeProvider;$options=New-Object CodeDom.Compiler.CompilerParameters;$options.GenerateExecutable=$false;$options.GenerateInMemory=$false;$options.OutputAssembly=$path;[void]$options.ReferencedAssemblies.Add('System.dll');[void]$options.ReferencedAssemblies.Add($exe);try{$result=$provider.CompileAssemblyFromSource($options,$source);if($result.Errors.HasErrors){throw (($result.Errors|%{$_.ToString()})-join' | ')}}finally{$provider.Dispose()};$path}
try{
  Assert($null-eq(Field 'ToolCatalogSelectionDetail')) 'Permanent selected-tool detail card still exists'
  $catalog=Field 'toolCatalog';$catalogItem=$catalog|Where-Object{$_.Kind.ToString()-eq'CSharpDllScript'}|Select-Object -First 1;Assert($null-ne$catalogItem) 'Script tool is missing from catalog';Assert(-not[string]::IsNullOrWhiteSpace($catalogItem.Category)) 'Script category is missing'
  $list=Field 'ToolCatalogList';Assert($list.ContextMenu.Items.Count-ge3) 'Toolbox contextual commands are incomplete'
  $mainType.GetField('toolCatalogMode',$private).SetValue($window,'All');$mainType.GetMethod('RefreshToolCatalogView',$private).Invoke($window,@())|Out-Null;$list.SelectedItem=$catalogItem;$mainType.GetMethod('ToolCatalogShowDescriptionMenuItem_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$catalogStatus=Field 'ToolCatalogStatusText';Assert($catalogStatus.Text-match'C# / DLL') 'Context description did not provide one-shot help';Assert((Field 'ToolCapabilityExpander').IsExpanded-and(Field 'ToolCapabilityPurposeText').Text-match'受信任扩展') 'S65 on-demand capability/port preview did not open';Assert($catalogStatus.TextWrapping.ToString()-eq'NoWrap'-and$catalogStatus.TextTrimming.ToString()-eq'CharacterEllipsis'-and-not[string]::IsNullOrWhiteSpace([string]$catalogStatus.ToolTip)) 'Compact status line regressed after S65 capability preview'
  $before=(Field 'flowTools').Count;$source=[Windows.PresentationSource]::FromVisual($window);$args=[Windows.Input.KeyEventArgs]::new([Windows.Input.Keyboard]::PrimaryDevice,$source,[Environment]::TickCount,[Windows.Input.Key]::Enter);$args.RoutedEvent=[Windows.Input.Keyboard]::PreviewKeyDownEvent;$mainType.GetMethod('ToolCatalogList_PreviewKeyDown',$private).Invoke($window,[object[]]@($list,$args))|Out-Null;Assert((Field 'flowTools').Count-eq($before+1)) 'Enter append regressed'

  $flow=Field 'flowTools';$input=Tool ImageSource 'Script Inputs';$script=Tool CSharpDllScript 'Custom Logic';$judge=Tool NumericJudge 'Script Judge';$text=Tool TextAssembly 'Script Text';foreach($tool in @($input,$script,$judge,$text)){$flow.Add($tool)}
  $input.SetOutputValue('Width',[double]7);$input.SetOutputValue('Height',[double]3);$input.SetOutputValue('SN','LOT-58');$input.SetOutputValue('ResultCode','OK');$input.ResultCode='OK'
  $script.SetInputBinding('NumberA',$input.ToolId,'Width');$script.SetInputBinding('NumberB',$input.ToolId,'Height');$script.SetInputBinding('String',$input.ToolId,'SN');$script.SetInputBinding('ResultCode',$input.ToolId,'ResultCode')
  $ports=$metadataType.GetMethod('GetInputPorts',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@((Kind CSharpDllScript)));$outputs=$metadataType.GetMethod('GetOutputPorts',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@((Kind CSharpDllScript)));Assert($ports.Count-eq4-and($ports|Where-Object{-not$_.IsOptional}).Count-eq0) 'Script typed optional input contract failed';foreach($name in @('Number','Text','ResultCode','IsOk','AssemblyVersion','AssemblySha256','Diagnostics','ExecutionMs')){Assert($null-ne($outputs|Where-Object{$_.PortName-eq$name}))('Missing script output '+$name)}
  $script.Parameters.ScriptExecutionMode='InlineCSharp';$script.Parameters.ScriptParameterNumber=2;$script.Parameters.ScriptParameterText='|P';$script.Parameters.ScriptInlineCode='double n=input.NumberA*input.ParameterNumber+input.NumberB; return ScriptToolResult.Ok(n,(input.Text ?? "")+"|"+input.ResultCode+input.ParameterText);'
  $record=Run $script;Assert($record.ResultCode-eq'OK'-and[double](Out $script Number)-eq17-and(Out $script Text)-eq'LOT-58|OK|P') 'Inline C# typed inputs/parameters/outputs failed';Assert(([string](Out $script AssemblySha256)).Length-eq64-and[double](Out $script ExecutionMs)-ge0) 'Inline assembly metadata missing'
  $judge.SetInputBinding('Value',$script.ToolId,'Number');$judge.InputToolId=$script.ToolId;$judge.InputPortName='Number';$judge.NumericLowerLimit=17;$judge.NumericUpperLimit=17;Assert((Run $judge).ResultCode-eq'OK') 'Script Number did not drive Numeric Judge'
  $text.SetInputBinding('String',$script.ToolId,'Text');$text.Parameters.TextAssemblyTemplate='SCRIPT={String}';Assert((Run $text).ResultCode-eq'OK'-and(Out $text Text)-eq'SCRIPT=LOT-58|OK|P') 'Script Text did not drive Text Assembly'

  $fixture=@'
using System.Reflection;
using HalconWinFormsDemo.Models;
[assembly: AssemblyVersion("2.5.8.0")]
namespace S58Fixture { public static class Entry { public static ScriptToolResult Execute(ScriptToolContext input) { return ScriptToolResult.Ok(input.ParameterNumber + (input.HasNumberA ? input.NumberA : 0), "DLL:" + input.ParameterText); } } }
'@
  $dll=CompileFixture $fixture 'S58Fixture.dll';$script.Parameters.ScriptExecutionMode='Dll';$script.Parameters.ScriptAssemblyPath=$dll;$script.Parameters.ScriptTypeName='S58Fixture.Entry';$script.Parameters.ScriptMethodName='Execute';$script.Parameters.ScriptParameterNumber=5;$script.Parameters.ScriptParameterText='REAL';Assert((Run $script).ResultCode-eq'OK'-and[double](Out $script Number)-eq12-and(Out $script Text)-eq'DLL:REAL') 'External DLL execution failed';Assert((Out $script AssemblyVersion)-eq'2.5.8.0'-and([string](Out $script AssemblySha256)).Length-eq64) 'DLL version/hash contract failed'

  $script.Parameters.ScriptExecutionMode='InlineCSharp';$script.Parameters.ScriptInlineCode='return ScriptToolResult.Ok(1, ;';Assert((RunFailure $script).Length-gt0) 'Compile diagnostics were not surfaced';Assert(([string](Out $script Diagnostics)).Length-gt0) 'Compile failure was not published to Diagnostics'
  $script.Parameters.ScriptInlineCode='System.Threading.Thread.Sleep(500); return ScriptToolResult.Ok(1,"late");';$script.Parameters.ScriptTimeoutMilliseconds=50;Assert((RunFailure $script).Length-gt0) 'Timeout was not enforced'
  $script.Parameters.ScriptTimeoutMilliseconds=1000;$script.Parameters.ScriptInlineCode='return ScriptToolResult.Ok(double.NaN,"bad");';Assert((RunFailure $script).Length-gt0) 'Nonfinite output was not rejected'
  $script.Parameters.ScriptExecutionMode='Dll';$script.Parameters.ScriptAssemblyPath=$dll;$script.Parameters.ScriptTypeName='Missing.Type';Assert((RunFailure $script).Length-gt0) 'Missing DLL type was not rejected'
  $script.Parameters.ScriptTypeName='S58Fixture.Entry';$script.Parameters.ScriptMethodName='Missing';Assert((RunFailure $script).Length-gt0) 'Missing DLL method was not rejected'
  $badSignature=CompileFixture 'using HalconWinFormsDemo.Models; namespace S58Bad { public static class Entry { public static double Execute(ScriptToolContext input) { return 1; } } }' 'S58Bad.dll';$script.Parameters.ScriptAssemblyPath=$badSignature;$script.Parameters.ScriptTypeName='S58Bad.Entry';$script.Parameters.ScriptMethodName='Execute';Assert((RunFailure $script).Length-gt0) 'Invalid DLL return signature was not rejected'
  $script.Parameters.ScriptAssemblyPath=(Join-Path $temp 'missing.dll');Assert((RunFailure $script).Length-gt0) 'Missing DLL file was not rejected'
  $script.Parameters.ScriptExecutionMode='InlineCSharp';$script.Parameters.ScriptInlineCode='throw new InvalidOperationException("fixture failure");';Assert((RunFailure $script).Length-gt0) 'Script runtime exception was not surfaced'
  $script.Parameters.ScriptExecutionMode='InlineCSharp';$script.Parameters.ScriptInlineCode='return ScriptToolResult.Ok(9,"restored");';Assert((Run $script).ResultCode-eq'OK') 'Script did not recover after failures'

  $serializer=[Runtime.Serialization.Json.DataContractJsonSerializer]::new($parametersType);$bytes=[Text.Encoding]::UTF8.GetBytes('{}');$stream=New-Object IO.MemoryStream(,$bytes);try{$old=$serializer.ReadObject($stream)}finally{$stream.Dispose()};$old.Normalize();Assert($old.ScriptExecutionMode-eq'InlineCSharp'-and$old.ScriptTimeoutMilliseconds-eq1000-and-not[string]::IsNullOrWhiteSpace($old.ScriptInlineCode)) 'Old recipe script defaults failed'
  LoadDock $script;Assert((Field 'DockScriptPanel').Visibility.ToString()-eq'Visible'-and-not(Field 'DockScriptEditorExpander').IsExpanded) 'Script dock is missing or editor is not progressively collapsed';(Field 'DockScriptEditorExpander').IsExpanded=$true;$mainType.GetMethod('DockScriptValidateButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;Assert((Field 'DockScriptDiagnosticsText').Text-match'InlineCSharp') 'Compile/entry validation did not report metadata';$oldNumber=$script.Parameters.ScriptParameterNumber;(Field 'DockScriptParameterNumberTextBox').Text='11';(Field 'DockScriptParameterTextTextBox').Text='DOCK';$apply=$mainType.GetMethod('ApplyDockConfigurationDraft',$private);Assert([bool]$apply.Invoke($window,[object[]]@($true))) 'Script dock Apply failed';Assert($script.Parameters.ScriptParameterNumber-eq11-and$script.Parameters.ScriptParameterText-eq'DOCK') 'Script dock values were not stored'
  $mainType.GetMethod('UndoFlowEditButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$restored=$flow|Where-Object{$_.ToolId-eq$script.ToolId}|Select-Object -First 1;Assert($restored.Parameters.ScriptParameterNumber-eq$oldNumber) 'Script undo failed';$mainType.GetMethod('RedoFlowEditButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$restored=$flow|Where-Object{$_.ToolId-eq$script.ToolId}|Select-Object -First 1;Assert($restored.Parameters.ScriptParameterNumber-eq11-and$restored.Parameters.ScriptParameterText-eq'DOCK') 'Script redo failed'
  LoadDock $restored;$flowList=Field 'FlowToolList';$flowList.SelectedItems.Clear();$flowList.SelectedItem=$restored;$copyBefore=$flow.Count;$mainType.GetMethod('DuplicateFlowToolButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$copy=$flow|Where-Object{$_.Kind.ToString()-eq'CSharpDllScript'-and$_.ToolId-ne$restored.ToolId}|Select-Object -Last 1;Assert($flow.Count-eq($copyBefore+1)-and$copy.Parameters.ScriptInlineCode-eq$restored.Parameters.ScriptInlineCode-and$copy.Parameters.ScriptParameterText-eq'DOCK') 'Script copy failed';$recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object{$_.ToolId-eq$restored.ToolId}|Select-Object -First 1;Assert($saved.Parameters.ScriptExecutionMode-eq'InlineCSharp'-and$saved.Parameters.ScriptParameterNumber-eq11) 'Script recipe persistence failed'
  Write-Output 'S58 progressive toolbox and trusted C#/DLL script flow/downstream/failure/recipe lifecycle passed; AppDomain isolation is not a security sandbox; BSB not implemented by user directive.'
}finally{$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if($ownsApp){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
